import { useMemo, useState } from "react";
import { Link } from "wouter";
import { startLogin } from "@/const";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import {
  ArrowRight, BadgeCheck, Bell, BriefcaseBusiness, Building2, Camera, Check, ChevronRight, CircleUserRound, Clock3,
  FileText, Flame, Loader2, LogOut, MapPin, Menu, Plus, Search, ShieldCheck, Sparkles, Star, Thermometer,
  Wrench, X, Zap
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";

const fallbackCategories = [
  { slug: "climatizacao", name: "Climatização", services: ["Instalação", "Manutenção preventiva", "Manutenção corretiva", "Higienização", "Diagnóstico", "PMOC", "Retirada", "Reinstalação", "Troca de equipamento"], equipment: ["Split", "Multi Split", "Cassete", "Piso-teto", "VRF/VRV", "Rooftop", "Central"] },
  { slug: "comercial", name: "Refrigeração comercial", services: ["Manutenção corretiva", "Diagnóstico", "Instalação", "Higienização"], equipment: ["Balcão refrigerado", "Expositor", "Freezer", "Ilha", "Geladeira comercial", "Máquina de gelo", "Câmara fria"] },
  { slug: "industrial", name: "Refrigeração industrial", services: ["Manutenção corretiva", "Diagnóstico", "Instalação", "PMOC"], equipment: ["Câmara fria", "Chiller", "Sistemas industriais", "Compressores", "Condensação"] },
  { slug: "residencial", name: "Refrigeração residencial", services: ["Manutenção corretiva", "Diagnóstico", "Instalação"], equipment: ["Geladeira", "Freezer", "Outros"] },
];
const fallbackCities = ["Cabo Frio", "Araruama", "São Pedro da Aldeia", "Arraial do Cabo", "Búzios", "Saquarema"];
const formatDate = (value: Date | string | null | undefined) => value ? new Date(value).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }) : "—";
const statusLabels: Record<string, string> = { open: "Aberta", matched: "Profissionais encontrados", interested: "Recebendo propostas", hired: "Contratado", in_progress: "Em execução", completed: "Concluído", canceled: "Cancelado" };
const statusColor: Record<string, string> = { open: "bg-slate-100 text-slate-700", matched: "bg-[#e3f3a4] text-[#375014]", interested: "bg-[#d9f2ed] text-[#0b6653]", hired: "bg-[#d6e4ff] text-[#244c89]", in_progress: "bg-[#fff0c7] text-[#76530a]", completed: "bg-[#dff4dc] text-[#2b7040]", canceled: "bg-red-100 text-red-700" };

type Persona = "customer" | "professional" | "admin";

function Logo({ light = false }: { light?: boolean }) {
  return <div className={`flex items-center gap-2 font-bold tracking-tight ${light ? "text-white" : "text-[#0c6b58]"}`}><span className="grid size-9 place-items-center rounded-xl bg-[#e3f3a4] text-[#27520f]"><Thermometer size={20} strokeWidth={2.5} /></span><span className="display text-[1.2rem]">Clima<span className={light ? "text-[#e3f3a4]" : "text-[#17211b]"}>Match</span></span></div>;
}

function TopBar({ onStart, onDashboard, onLogout, user }: { onStart: () => void; onDashboard: () => void; onLogout: () => void; user: any }) {
  const [open, setOpen] = useState(false);
  return <header className="absolute inset-x-0 top-0 z-20"><div className="container flex h-20 items-center justify-between"><Logo light /><nav className="hidden items-center gap-8 text-sm text-white/75 md:flex"><a href="#como-funciona" className="hover:text-white">Como funciona</a><a href="#categorias" className="hover:text-white">Especialidades</a><a href="#seguranca" className="hover:text-white">Segurança</a></nav><div className="hidden items-center gap-3 md:flex">{user ? <><button onClick={onDashboard} className="rounded-full px-4 py-2 text-sm text-white/80 hover:bg-white/10 hover:text-white">Meu painel</button><button onClick={onLogout} className="flex items-center gap-2 rounded-full border border-white/20 px-4 py-2 text-sm text-white/90 hover:bg-white/10"><LogOut size={15} /> Sair</button></> : <><button onClick={onStart} className="rounded-full px-4 py-2 text-sm text-white/80 hover:bg-white/10">Entrar</button><button onClick={onStart} className="rounded-full bg-[#e3f3a4] px-5 py-2.5 text-sm font-bold text-[#29440e] shadow-[0_8px_24px_rgba(227,243,164,.2)] hover:bg-[#effbbd]">Começar agora</button></>}</div><Sheet open={open} onOpenChange={setOpen}><SheetTrigger asChild><button className="grid size-10 place-items-center rounded-xl border border-white/20 text-white md:hidden" aria-label="Abrir menu"><Menu size={19} /></button></SheetTrigger><SheetContent className="w-[300px] bg-[#0c332d] text-white"><div className="mb-10"><Logo light /></div><div className="flex flex-col gap-4"><a href="#como-funciona" onClick={() => setOpen(false)}>Como funciona</a><a href="#categorias" onClick={() => setOpen(false)}>Especialidades</a><button className="mt-4 rounded-xl bg-[#e3f3a4] px-4 py-3 text-left font-bold text-[#29440e]" onClick={() => { setOpen(false); onStart(); }}>{user ? "Abrir meu painel" : "Solicitar serviço"}</button></div></SheetContent></Sheet></div></header>;
}

function Hero({ onStart, onProfessional, onDashboard, user, onLogout }: { onStart: () => void; onProfessional: () => void; onDashboard: () => void; user: any; onLogout: () => void }) {
  return (
    <section className="relative min-h-[680px] overflow-hidden bg-[#0b332d] text-white">
      <div className="absolute -right-28 -top-28 size-[520px] rounded-full border border-white/10" />
      <div className="absolute -right-8 top-24 size-[360px] rounded-full border border-white/10" />
      <div className="absolute bottom-[-180px] left-[-80px] size-[420px] rounded-full bg-[#144e42] opacity-60 blur-3xl" />
      <TopBar onStart={onStart} onDashboard={onDashboard} onLogout={onLogout} user={user} />
      <div className="container relative grid items-center gap-12 pb-20 pt-36 md:min-h-[680px] md:grid-cols-[1.08fr_.92fr] md:pb-24 md:pt-32">
        <div className="max-w-2xl">
          <div className="mb-7 inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/5 px-3.5 py-2 text-xs font-medium text-[#d5e5d5]"><span className="size-2 rounded-full bg-[#e3f3a4]" /> Região dos Lagos, RJ · demanda local</div>
          <h1 className="display text-5xl font-semibold leading-[.98] tracking-[-.06em] md:text-7xl">O serviço certo.<br /><span className="text-[#e3f3a4]">Sem complicação.</span></h1>
          <p className="mt-7 max-w-xl text-lg leading-8 text-white/68 md:text-xl">Conectamos você a profissionais de climatização e refrigeração que entendem do assunto — perto de onde você está.</p>
          <div className="mt-9 flex flex-col gap-3 sm:flex-row"><Button onClick={onStart} className="h-14 rounded-2xl bg-[#e3f3a4] px-7 text-base font-bold text-[#29440e] shadow-[0_12px_30px_rgba(227,243,164,.16)] hover:bg-[#effbbd]"><Plus size={19} /> Solicitar serviço</Button><Button onClick={onProfessional} variant="outline" className="h-14 rounded-2xl border-white/20 bg-transparent px-7 text-base font-semibold text-white hover:bg-white/10 hover:text-white"><Wrench size={18} /> Sou profissional</Button></div>
          <div className="mt-10 flex items-center gap-6 text-sm text-white/60"><span className="flex items-center gap-2"><ShieldCheck size={17} className="text-[#e3f3a4]" /> Profissionais avaliados</span><span className="flex items-center gap-2"><MapPin size={17} className="text-[#e3f3a4]" /> Atendimento regional</span></div>
        </div>
        <div className="relative hidden h-[430px] md:block">
          <div className="absolute right-4 top-6 w-[330px] rotate-3 rounded-[28px] bg-[#e3f3a4] p-5 text-[#28470e] shadow-2xl">
            <div className="flex items-center justify-between text-xs font-bold uppercase tracking-[.18em] opacity-65"><span>Solicitação #1842</span><span className="rounded-full bg-[#cfe77f] px-2 py-1">Aberta</span></div>
            <h3 className="display mt-7 text-3xl font-semibold leading-tight">Ar-condicionado<br />não está gelando</h3>
            <div className="mt-7 flex items-center justify-between border-t border-[#accb63] pt-4 text-sm"><span>Split · LG · 12.000 BTUs</span><span className="flex items-center gap-1"><MapPin size={14} /> Cabo Frio</span></div>
          </div>
          <div className="absolute bottom-2 left-4 w-[300px] -rotate-6 rounded-[24px] border border-white/15 bg-white/10 p-5 backdrop-blur-xl">
            <div className="flex items-center gap-3"><div className="grid size-12 place-items-center rounded-2xl bg-[#f4c36a] text-[#6e4311]"><BriefcaseBusiness size={22} /></div><div><p className="font-semibold">3 profissionais encontrados</p><p className="mt-1 text-sm text-white/60">Compatíveis com sua região</p></div></div>
            <div className="mt-5 flex -space-x-2"><div className="grid size-9 place-items-center rounded-full border-2 border-[#0b332d] bg-[#efc4a5] text-xs font-bold text-[#7a4831]">RA</div><div className="grid size-9 place-items-center rounded-full border-2 border-[#0b332d] bg-[#b8d6c5] text-xs font-bold text-[#295944]">MS</div><div className="grid size-9 place-items-center rounded-full border-2 border-[#0b332d] bg-[#b9c7e9] text-xs font-bold text-[#384f87]">JP</div><div className="ml-3 self-center text-xs text-white/60">e mais na região</div></div>
          </div>
        </div>
      </div>
      <div className="absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-[#f7f4ee] to-transparent" />
    </section>
  );
}

function SectionHeader({ eyebrow, title, copy }: { eyebrow: string; title: string; copy: string }) { return <div className="max-w-2xl"><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] text-[#0c6b58]">{eyebrow}</p><h2 className="display text-4xl font-semibold leading-tight md:text-5xl">{title}</h2><p className="mt-5 text-lg leading-8 text-[#6d776f]">{copy}</p></div>; }

function Landing({ onStart, onProfessional, onDashboard, user, onLogout }: any) {
  return <div><Hero onStart={onStart} onProfessional={onProfessional} onDashboard={onDashboard} user={user} onLogout={onLogout} /><section id="como-funciona" className="container py-24 md:py-32"><SectionHeader eyebrow="Do chamado à solução" title="Tudo organizado em um só lugar." copy="Você conta o que aconteceu. A gente encontra quem sabe resolver. Sem lista infinita de contatos, sem indicação no escuro." /><div className="mt-14 grid gap-5 md:grid-cols-3"><Step number="01" icon={<FileText size={23} />} title="Conte o que aconteceu" copy="Use suas próprias palavras. Você não precisa saber o nome técnico do problema." /><Step number="02" icon={<Search size={23} />} title="Receba compatibilidade" copy="A plataforma organiza o chamado e encontra profissionais da sua região." /><Step number="03" icon={<Check size={23} />} title="Escolha com confiança" copy="Compare propostas, contrate e avalie o serviço quando estiver concluído." /></div></section><section id="categorias" className="bg-[#e8efe9] py-24 md:py-28"><div className="container"><SectionHeader eyebrow="Especialidades" title="Do split à câmara fria." copy="Uma rede especializada para os equipamentos que fazem sua casa e seu negócio funcionarem." /><div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><CategoryCard icon={<Thermometer />} title="Climatização" desc="Split, cassete, VRF e mais." tone="mint" /><CategoryCard icon={<Building2 />} title="Refrigeração comercial" desc="Expositores, freezers e câmaras." tone="sand" /><CategoryCard icon={<Zap />} title="Refrigeração industrial" desc="Chillers, compressores e sistemas." tone="lavender" /><CategoryCard icon={<CircleUserRound />} title="Refrigeração residencial" desc="Geladeira, freezer e outros." tone="peach" /></div></div></section><section id="seguranca" className="container py-24 md:py-32"><div className="grid gap-14 md:grid-cols-[.9fr_1.1fr] md:items-center"><div><div className="grid size-16 place-items-center rounded-2xl bg-[#e3f3a4] text-[#0c6b58]"><ShieldCheck size={31} /></div><h2 className="display mt-7 text-4xl font-semibold leading-tight md:text-5xl">Feito para gerar confiança dos dois lados.</h2><p className="mt-5 text-lg leading-8 text-[#6d776f]">Cada serviço cria um histórico real. A plataforma organiza o fluxo inteiro para que clientes e profissionais tenham clareza em cada etapa.</p><Button onClick={onStart} className="mt-8 rounded-xl bg-[#0c6b58] px-6 py-5 font-semibold text-white hover:bg-[#095443]">Começar agora <ArrowRight size={17} /></Button></div><div className="grid gap-4 sm:grid-cols-2"><TrustCard icon={<MapPin />} title="Perto de você" copy="Começamos pela Região dos Lagos para criar densidade de verdade." /><TrustCard icon={<BadgeCheck />} title="Profissionais avaliados" copy="Reputação nasce de serviços reais concluídos na plataforma." /><TrustCard icon={<Bell />} title="Acompanhamento" copy="Você sabe quando sua solicitação avançou de etapa." /><TrustCard icon={<Flame />} title="Urgência clara" copy="A prioridade fica visível para quem pode atender mais rápido." /></div></div></section><footer className="border-t border-[#dce4da] py-8"><div className="container flex flex-col justify-between gap-4 text-sm text-[#718079] sm:flex-row sm:items-center"><Logo /><span>ClimaMatch · Cabo Frio e Região dos Lagos</span></div></footer></div>;
}
function Step({ number, icon, title, copy }: any) { return <div className="rounded-3xl border border-[#dde3d9] bg-[#fffdf8] p-6 shadow-[0_14px_40px_rgba(23,33,27,.04)]"><div className="flex items-center justify-between"><div className="grid size-12 place-items-center rounded-2xl bg-[#e8efe9] text-[#0c6b58]">{icon}</div><span className="display text-4xl font-semibold text-[#dce7db]">{number}</span></div><h3 className="mt-7 text-xl font-bold">{title}</h3><p className="mt-3 leading-7 text-[#6d776f]">{copy}</p></div>; }
function CategoryCard({ icon, title, desc, tone }: any) { const toneMap: any = { mint: "bg-[#d7f1e7] text-[#0c6b58]", sand: "bg-[#f7dfb1] text-[#805522]", lavender: "bg-[#d9d9f5] text-[#4d4d8e]", peach: "bg-[#f5d4c5] text-[#914f3c]" }; return <div className="rounded-3xl bg-[#fffdf8] p-5 shadow-[0_14px_40px_rgba(23,33,27,.05)]"><div className={`grid size-12 place-items-center rounded-2xl ${toneMap[tone]}`}>{icon}</div><h3 className="mt-6 font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#6d776f]">{desc}</p></div>; }
function TrustCard({ icon, title, copy }: any) { return <div className="rounded-3xl bg-[#fffdf8] p-5 shadow-[0_14px_40px_rgba(23,33,27,.05)]"><div className="text-[#0c6b58]">{icon}</div><h3 className="mt-5 font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-[#6d776f]">{copy}</p></div>; }

function DashboardShell({ persona, setPersona, user, onLogout, children }: any) {
  const [mobile, setMobile] = useState(false);
  const nav = [{ id: "customer", label: "Meu painel", icon: <CircleUserRound size={17} /> }, { id: "professional", label: "Oportunidades", icon: <BriefcaseBusiness size={17} /> }, ...(user?.role === "admin" ? [{ id: "admin", label: "Visão admin", icon: <ShieldCheck size={17} /> }] : [])];
  return <div className="min-h-screen bg-[#f7f4ee]"><aside className="fixed inset-y-0 left-0 z-30 hidden w-[250px] flex-col border-r border-[#dce4da] bg-[#fbfaf5] px-5 py-6 md:flex"><Logo /><p className="mt-12 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-[#9aa79e]">Workspace</p><nav className="mt-3 space-y-1">{nav.map((item: any) => <button key={item.id} onClick={() => setPersona(item.id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${persona === item.id ? "bg-[#dff0e7] text-[#0c6b58]" : "text-[#718079] hover:bg-[#eef2eb]"}`}>{item.icon}{item.label}</button>)}</nav><div className="mt-auto rounded-2xl bg-[#0b332d] p-4 text-white"><p className="text-xs text-white/55">Região inicial</p><p className="mt-1 font-semibold">Cabo Frio e entorno</p><div className="mt-4 flex items-center gap-2 text-xs text-[#e3f3a4]"><MapPin size={13} /> 6 cidades conectadas</div></div></aside><main className="md:pl-[250px]"><header className="sticky top-0 z-20 border-b border-[#dce4da]/80 bg-[#f7f4ee]/90 backdrop-blur-xl"><div className="flex h-[76px] items-center justify-between px-5 md:px-10"><div className="flex items-center gap-3"><button onClick={() => setMobile(!mobile)} className="grid size-10 place-items-center rounded-xl border border-[#dce4da] bg-[#fffdf8] md:hidden"><Menu size={18} /></button><div><p className="text-xs font-bold uppercase tracking-[.16em] text-[#93a098]">Olá{user?.name ? `, ${user.name.split(" ")[0]}` : " por aqui"}</p><h1 className="display mt-1 text-xl font-semibold">{persona === "customer" ? "Visão geral" : persona === "professional" ? "Oportunidades para você" : "Pulso do marketplace"}</h1></div></div><div className="flex items-center gap-2"><button className="grid size-10 place-items-center rounded-xl border border-[#dce4da] bg-[#fffdf8] text-[#6d776f]"><Bell size={17} /></button><button onClick={onLogout} className="hidden items-center gap-2 rounded-xl border border-[#dce4da] bg-[#fffdf8] px-3 py-2 text-sm text-[#66746c] sm:flex"><LogOut size={15} /> Sair</button></div></div></header>{mobile && <div className="border-b border-[#dce4da] bg-[#fbfaf5] p-4 md:hidden"><div className="flex gap-2 overflow-x-auto">{nav.map((item: any) => <button key={item.id} onClick={() => { setPersona(item.id); setMobile(false); }} className={`flex shrink-0 items-center gap-2 rounded-xl px-3 py-2 text-sm font-semibold ${persona === item.id ? "bg-[#0c6b58] text-white" : "bg-[#e8efe9] text-[#0c6b58]"}`}>{item.icon}{item.label}</button>)}</div></div>}{children}</main></div>;
}

function Dashboard({ persona, setPersona, onRequest, user, onLogout }: any) {
  return <DashboardShell persona={persona} setPersona={setPersona} user={user} onLogout={onLogout}>{persona === "customer" && <CustomerPanel onRequest={onRequest} />}{persona === "professional" && <ProfessionalPanel />}{persona === "admin" && <AdminPanel />}</DashboardShell>;
}

function ServiceReviewCard({ service }: { service: any }) {
  const [overall, setOverall] = useState(5); const [quality, setQuality] = useState(5); const [punctuality, setPunctuality] = useState(5); const [serviceScore, setServiceScore] = useState(5); const [comment, setComment] = useState("");
  const review = trpc.service.review.useMutation({ onSuccess: () => toast.success("Obrigado pela avaliação!"), onError: e => toast.error(e.message) });
  const stars = (value: number, setValue: (value: number) => void) => <div className="flex gap-1">{[1,2,3,4,5].map(star => <button key={star} type="button" onClick={() => setValue(star)} aria-label={`${star} estrelas`}><Star size={20} className={star <= value ? "fill-[#f4b942] text-[#f4b942]" : "text-[#cbd8cc]"} /></button>)}</div>;
  const ratings: Array<[string, number, (value: number) => void]> = [["Nota geral", overall, setOverall], ["Qualidade", quality, setQuality], ["Pontualidade", punctuality, setPunctuality], ["Atendimento", serviceScore, setServiceScore]];
  return <Card className="mt-8 border-[#f0d79f] bg-[#fff9e9] shadow-none"><CardHeader><CardTitle className="flex items-center gap-2 text-lg"><Star className="fill-[#f4b942] text-[#f4b942]" size={19} /> Como foi o serviço?</CardTitle><p className="text-sm text-[#7d6b42]">Sua avaliação ajuda outros clientes a escolherem bons profissionais.</p></CardHeader><CardContent><div className="grid gap-4 sm:grid-cols-2">{ratings.map(([label, value, setter]) => <div key={label} className="rounded-xl bg-white/70 p-3"><p className="mb-2 text-xs font-bold text-[#80652b]">{label}</p>{stars(value, setter)}</div>)}</div><textarea value={comment} onChange={e => setComment(e.target.value)} className="mt-4 min-h-[90px] w-full rounded-xl border border-[#ead8a7] bg-white px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-[#f0d79f]" placeholder="Conte brevemente como foi sua experiência (opcional)." /><Button disabled={review.isPending} onClick={() => review.mutate({ serviceId: service.id, overall, quality, punctuality, service: serviceScore, comment })} className="mt-4 rounded-xl bg-[#0c6b58] text-white">{review.isPending ? <Loader2 className="animate-spin" /> : <Star size={16} />} Enviar avaliação</Button></CardContent></Card>;
}

function CustomerPanel({ onRequest }: { onRequest: () => void }) {
  const { data: requests, isLoading } = trpc.requests.mine.useQuery();
  const { data: services } = trpc.service.mine.useQuery();
  const [selectedRequest, setSelectedRequest] = useState<number | null>(null);
  const proposalQuery = trpc.proposals.forRequest.useQuery({ requestId: selectedRequest ?? 0 }, { enabled: !!selectedRequest });
  const choose = trpc.proposals.choose.useMutation({ onSuccess: () => { toast.success("Profissional contratado. O serviço foi criado!"); proposalQuery.refetch(); }, onError: (e) => toast.error(e.message) });
  const list = requests ?? [];
  return <div className="container py-8 md:py-10"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-sm text-[#6d776f]">Acompanhe tudo por aqui</p><h2 className="display mt-2 text-3xl font-semibold md:text-4xl">Minhas solicitações</h2></div><Button onClick={onRequest} className="rounded-xl bg-[#0c6b58] px-5 py-5 font-semibold text-white hover:bg-[#095443]"><Plus size={17} /> Solicitar serviço</Button></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><Stat label="Solicitações abertas" value={String(list.filter((x: any) => !["completed", "canceled"].includes(x.status)).length)} icon={<FileText />} /><Stat label="Propostas recebidas" value={selectedRequest && proposalQuery.data ? String(proposalQuery.data.length) : "—"} icon={<Sparkles />} /><Stat label="Serviços ativos" value={String((services ?? []).filter((x: any) => ["hired", "in_progress"].includes(x.status)).length)} icon={<Wrench />} /></div>{(services ?? []).filter((service: any) => service.status === "completed").map((service: any) => <ServiceReviewCard key={service.id} service={service} />)}<div className="mt-10 grid gap-6 lg:grid-cols-[1.08fr_.92fr]"><Card className="border-[#dce4da] bg-[#fffdf8] shadow-none"><CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-lg">Solicitações recentes</CardTitle><span className="text-xs font-semibold text-[#89958d]">{list.length} no total</span></CardHeader><CardContent>{isLoading ? <Loader2 className="animate-spin text-[#0c6b58]" /> : list.length === 0 ? <EmptyState icon={<FileText />} title="Sua próxima solicitação começa aqui" copy="Descreva o problema e encontre profissionais compatíveis na sua cidade." action="Criar solicitação" onClick={onRequest} /> : <div className="space-y-3">{list.map((request: any) => <div key={request.id} className="rounded-2xl border border-[#e4e9e2] bg-[#fbfaf5] p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><div className="flex items-center gap-2"><span className="text-xs font-bold text-[#8a968e]">#{request.id}</span><Badge className={`border-0 ${statusColor[request.status]}`}>{statusLabels[request.status]}</Badge></div><h3 className="mt-2 font-bold">{request.description.split(". Ambiente")[0]}</h3><p className="mt-1 text-sm text-[#718079]">{request.city} · criada em {formatDate(request.createdAt)}</p></div>{["matched", "interested"].includes(request.status) && <Button onClick={() => setSelectedRequest(request.id)} variant="outline" className="rounded-xl border-[#cbd8cc] bg-transparent text-[#0c6b58]">Ver propostas <ChevronRight size={15} /></Button>}</div>{selectedRequest === request.id && <div className="mt-4 border-t border-[#e4e9e2] pt-4">{proposalQuery.isLoading ? <Loader2 className="animate-spin" /> : proposalQuery.data?.length ? <div className="space-y-3">{proposalQuery.data.map((proposal: any) => <div key={proposal.id} className="flex flex-col justify-between gap-3 rounded-xl bg-white p-3 sm:flex-row sm:items-center"><div><p className="font-bold text-[#0c6b58]">R$ {Number(proposal.amount).toLocaleString("pt-BR", { minimumFractionDigits: 2 })}</p><p className="text-sm text-[#495a50]">{proposal.description}</p><p className="mt-1 text-xs text-[#8b978f]">Prazo: {proposal.deadline}</p></div><Button disabled={choose.isPending} onClick={() => choose.mutate({ proposalId: proposal.id })} className="rounded-lg bg-[#0c6b58] text-white">Escolher</Button></div>)}</div> : <p className="text-sm text-[#718079]">Ainda não há propostas. Oportunidade enviada aos profissionais compatíveis.</p>}</div>}</div>)}</div>}</CardContent></Card><Card className="border-[#dce4da] bg-[#0b332d] text-white shadow-none"><CardHeader><CardTitle className="text-lg">Próximos passos</CardTitle></CardHeader><CardContent className="space-y-5">{[{ icon: <Search />, title: "Aguarde os profissionais", copy: "Sua solicitação já foi direcionada para quem atende sua região." }, { icon: <FileText />, title: "Compare propostas", copy: "Quando chegarem, você poderá ver valor, prazo e observações." }, { icon: <Star />, title: "Avalie ao concluir", copy: "Sua avaliação ajuda a fortalecer a rede local." }].map((item, index) => <div key={item.title} className="flex gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-xl bg-white/10 text-[#e3f3a4]">{item.icon}</div><div><p className="font-semibold">{index + 1}. {item.title}</p><p className="mt-1 text-sm leading-6 text-white/58">{item.copy}</p></div></div>)}</CardContent></Card></div></div>;
}

function listValues(value: string | null | undefined) { return (value ?? '').split(',').map(item => item.trim()).filter(Boolean); }

function ProfileShowcase({ profile }: { profile: any }) {
  const services = listValues(profile.serviceTypes);
  const certifications = listValues(profile.certifications);
  const specialties = listValues(profile.specialties);
  return <Card className="mt-8 overflow-hidden border-[#bfd8c7] bg-[#0b332d] text-white shadow-none"><CardContent className="p-0"><div className="flex flex-col justify-between gap-6 p-6 md:flex-row md:items-start md:p-8"><div><div className="flex items-center gap-3"><div className="grid size-14 place-items-center rounded-2xl bg-[#e3f3a4] text-[#0c6b58]"><Wrench size={25} /></div><div><div className="flex items-center gap-2"><h3 className="text-2xl font-bold">{profile.businessName || 'Profissional ClimaMatch'}</h3>{profile.verified && <BadgeCheck size={19} className="text-[#e3f3a4]" />}</div><p className="mt-1 text-sm text-white/60">{profile.experienceYears} anos de experiência · {profile.availability}</p></div></div><p className="mt-5 max-w-2xl leading-7 text-white/75">{profile.bio || 'Apresente seu trabalho e deixe claro por que clientes podem confiar em você.'}</p><div className="mt-4 flex flex-wrap gap-2">{specialties.map(item => <span key={item} className="rounded-full bg-white/10 px-3 py-1.5 text-xs font-semibold text-[#e3f3a4]">{item}</span>)}{listValues(profile.cities).map(item => <span key={item} className="flex items-center gap-1 rounded-full bg-white/10 px-3 py-1.5 text-xs text-white/75"><MapPin size={12} /> {item}</span>)}</div></div><div className="grid min-w-[210px] gap-3 sm:grid-cols-2 md:grid-cols-1"><div className="rounded-2xl bg-white/10 p-4"><p className="text-xs uppercase tracking-[.16em] text-white/50">Avaliação</p><p className="mt-1 text-2xl font-bold text-[#e3f3a4]">{profile.rating || 'Novo'}</p><p className="text-xs text-white/55">{profile.reviewCount} avaliações</p></div><div className="rounded-2xl bg-white/10 p-4"><p className="text-xs uppercase tracking-[.16em] text-white/50">Atende</p><p className="mt-1 font-bold text-white">{listValues(profile.cities).length} cidades</p></div></div></div><div className="grid gap-4 border-t border-white/10 bg-white/5 p-6 md:grid-cols-2 md:p-8"><div><p className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.16em] text-[#e3f3a4]"><Wrench size={14} /> Tipos de serviço</p><div className="mt-3 flex flex-wrap gap-2">{services.length ? services.map(item => <span key={item} className="rounded-xl bg-[#e3f3a4] px-3 py-2 text-sm font-bold text-[#29440e]">{item}</span>) : <span className="text-sm text-white/55">Adicione seus serviços no perfil.</span>}</div></div><div><p className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.16em] text-[#f4c36a]"><BadgeCheck size={14} /> Certificações</p><div className="mt-3 flex flex-wrap gap-2">{certifications.length ? certifications.map(item => <span key={item} className="flex items-center gap-2 rounded-xl border border-[#f4c36a]/40 bg-[#f4c36a]/10 px-3 py-2 text-sm font-semibold text-[#f7d78f]"><BadgeCheck size={14} /> {item}</span>) : <span className="text-sm text-white/55">Adicione suas certificações no perfil.</span>}</div></div></div></CardContent></Card>;
}

function MediaGallery({ photos }: { photos?: string | null }) {
  const media = (photos ?? '').split(',').map(item => item.trim()).filter(Boolean);
  if (!media.length) return null;
  return <div className="mt-4 rounded-2xl border border-[#dce4da] bg-white p-3"><div className="mb-3 flex items-center gap-2 text-xs font-bold uppercase tracking-[.14em] text-[#0c6b58]"><Camera size={14} /> Fotos e vídeos do cliente</div><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">{media.map((url, index) => url.match(/\.(mp4|mov)(_|$)/i) ? <video key={url} src={url} controls className="aspect-video w-full rounded-xl bg-black object-cover" /> : <a key={url} href={url} target="_blank" rel="noreferrer" className="group relative block overflow-hidden rounded-xl"><img src={url} alt={`Anexo do cliente ${index + 1}`} className="aspect-video w-full object-cover transition group-hover:scale-105" /><span className="absolute bottom-2 right-2 rounded-full bg-black/60 px-2 py-1 text-xs text-white">Abrir</span></a>)}</div></div>;
}

function ProfessionalPanel() {
  const profileQuery = trpc.profile.me.useQuery();
  const { data: opportunities, isLoading } = trpc.professional.opportunities.useQuery();
  const { data: proposals } = trpc.professional.proposals.useQuery();
  const { data: services } = trpc.professional.services.useQuery();
  const { data: notifications } = trpc.professional.notifications.useQuery();
  const save = trpc.profile.saveProfessional.useMutation({ onSuccess: () => { toast.success('Perfil profissional salvo'); profileQuery.refetch(); }, onError: e => toast.error(e.message) });
  const interest = trpc.professional.interest.useMutation({ onSuccess: () => toast.success('Interesse registrado'), onError: e => toast.error(e.message) });
  const sendProposal = trpc.professional.sendProposal.useMutation({ onSuccess: () => { toast.success('Proposta enviada ao cliente'); setActive(null); }, onError: e => toast.error(e.message) });
  const markRead = trpc.professional.markNotificationRead.useMutation();
  const [active, setActive] = useState<number | null>(null);
  const [profileForm, setProfileForm] = useState({ businessName: '', phone: '', bio: '', cities: 'Cabo Frio', specialties: 'climatizacao', equipmentTypes: 'Split', serviceTypes: 'Diagnóstico, Manutenção corretiva', certifications: '', experienceYears: 5, availability: 'Seg a Sex · 8h às 18h' });
  const [proposalForm, setProposalForm] = useState({ amount: '', deadline: 'Até 3 dias úteis', description: '', notes: '' });
  const profile = profileQuery.data?.professional;
  const submitProfile = () => save.mutate({ ...profileForm, cities: profileForm.cities.split(',').map(x => x.trim()).filter(Boolean), specialties: profileForm.specialties.split(',').map(x => x.trim()).filter(Boolean), equipmentTypes: profileForm.equipmentTypes.split(',').map(x => x.trim()).filter(Boolean), serviceTypes: profileForm.serviceTypes.split(',').map(x => x.trim()).filter(Boolean), certifications: profileForm.certifications.split(',').map(x => x.trim()).filter(Boolean) });
  return <div className="container py-8 md:py-10"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-sm text-[#6d776f]">Encontre trabalho compatível</p><h2 className="display mt-2 text-3xl font-semibold md:text-4xl">Oportunidades para você</h2></div><div className="flex items-center gap-2 rounded-full bg-[#e3f3a4] px-3 py-2 text-xs font-bold text-[#375014]"><span className="size-2 rounded-full bg-[#5e8c19]" /> Perfil regional ativo</div></div>{profile ? <ProfileShowcase profile={profile} /> : <Card className="mt-8 border-[#c8ded2] bg-[#e9f5ee] shadow-none"><CardHeader><CardTitle className="flex items-center gap-2 text-lg"><Sparkles size={18} className="text-[#0c6b58]" /> Configure seu perfil para receber matches</CardTitle><p className="text-sm text-[#5f7368]">Quanto mais completo o perfil, mais certeiras ficam as oportunidades.</p></CardHeader><CardContent><div className="grid gap-4 md:grid-cols-2"><Field label="Nome da empresa ou como quer ser chamado" value={profileForm.businessName} onChange={v => setProfileForm({ ...profileForm, businessName: v })} placeholder="Ex.: Refrigeração Costa Azul" /><Field label="Telefone" value={profileForm.phone} onChange={v => setProfileForm({ ...profileForm, phone: v })} placeholder="(22) 99999-0000" /><Field label="Cidades atendidas" value={profileForm.cities} onChange={v => setProfileForm({ ...profileForm, cities: v })} placeholder="Separe por vírgula" /><Field label="Especialidades" value={profileForm.specialties} onChange={v => setProfileForm({ ...profileForm, specialties: v })} placeholder="climatizacao, comercial" /><Field label="Equipamentos" value={profileForm.equipmentTypes} onChange={v => setProfileForm({ ...profileForm, equipmentTypes: v })} placeholder="Split, Chiller" /><Field label="Tipos de serviço" value={profileForm.serviceTypes} onChange={v => setProfileForm({ ...profileForm, serviceTypes: v })} placeholder="Diagnóstico, instalação" /><Field label="Certificações" value={profileForm.certifications} onChange={v => setProfileForm({ ...profileForm, certifications: v })} placeholder="Ex.: NR-10, PMOC" /><Field label="Anos de experiência" value={String(profileForm.experienceYears)} onChange={v => setProfileForm({ ...profileForm, experienceYears: Number(v) || 0 })} type="number" /></div><label className="mt-4 block text-sm font-semibold">Sobre seu trabalho<textarea value={profileForm.bio} onChange={e => setProfileForm({ ...profileForm, bio: e.target.value })} className="mt-2 min-h-[90px] w-full rounded-xl border border-[#cfe0d4] bg-white px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-[#9bc9af]" placeholder="Conte brevemente o que você faz melhor." /></label><Button onClick={submitProfile} disabled={save.isPending} className="mt-5 rounded-xl bg-[#0c6b58] text-white">{save.isPending && <Loader2 className="animate-spin" />} Salvar perfil</Button></CardContent></Card>}<div className="mt-8 grid gap-4 sm:grid-cols-3"><Stat label="Novas oportunidades" value={String(opportunities?.length ?? 0)} icon={<BriefcaseBusiness />} /><Stat label="Propostas enviadas" value={String(proposals?.length ?? 0)} icon={<FileText />} /><Stat label="Serviços ativos" value={String((services ?? []).filter((x: any) => x.status !== 'completed').length)} icon={<Wrench />} /></div><div className="mt-8 grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><Card className="border-[#dce4da] bg-[#fffdf8] shadow-none"><CardHeader><CardTitle className="flex items-center gap-2 text-lg"><Bell size={18} className="text-[#0c6b58]" /> Notificações</CardTitle></CardHeader><CardContent>{!notifications?.length ? <p className="text-sm text-[#718079]">Quando surgir um chamado compatível, ele aparecerá aqui.</p> : <div className="space-y-3">{notifications.slice(0, 6).map((item: any) => <button key={item.id} onClick={() => !item.read && markRead.mutate({ notificationId: item.id })} className={`w-full rounded-xl p-3 text-left ${item.read ? 'bg-[#fbfaf5]' : 'bg-[#e8efe9]'}`}><div className="flex items-start gap-2"><Bell size={15} className="mt-0.5 shrink-0 text-[#0c6b58]" /><div><p className="text-sm font-bold">{item.title}</p><p className="mt-1 text-xs leading-5 text-[#718079]">{item.message}</p></div>{!item.read && <span className="ml-auto size-2 shrink-0 rounded-full bg-[#f4a340]" />}</div></button>)}</div>}</CardContent></Card><Card className="border-[#dce4da] bg-[#fffdf8] shadow-none"><CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-lg">Oportunidades compatíveis</CardTitle><Badge variant="outline" className="rounded-full border-[#bed3c5] text-[#0c6b58]">{opportunities?.length ?? 0} abertas</Badge></CardHeader><CardContent>{isLoading ? <Loader2 className="animate-spin text-[#0c6b58]" /> : !opportunities?.length ? <EmptyState icon={<BriefcaseBusiness />} title="Ainda não há oportunidades" copy="Quando surgir uma solicitação na sua região, ela aparece aqui." /> : <div className="space-y-3">{opportunities.map((opportunity: any) => <div key={opportunity.id} className="rounded-2xl border border-[#e4e9e2] bg-[#fbfaf5] p-4"><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><Badge className="border-0 bg-[#dff0e7] text-[#0c6b58]">Match regional</Badge>{opportunity.urgency !== 'normal' && <Badge className="border-0 bg-[#ffe2cb] text-[#8a4d24]">{opportunity.urgency}</Badge>}</div><h3 className="mt-3 font-bold">{opportunity.serviceType} · {opportunity.equipment}</h3><p className="mt-1 flex items-center gap-1 text-sm text-[#718079]"><MapPin size={14} /> {opportunity.city} · {opportunity.availability}</p><p className="mt-3 text-sm leading-6 text-[#52645a]">{opportunity.description}</p></div><span className="rounded-lg bg-white px-2 py-1 text-xs font-bold text-[#8a968e]">#{opportunity.id}</span></div><MediaGallery photos={opportunity.photos} /><div className="mt-4 flex flex-wrap gap-2 border-t border-[#e4e9e2] pt-3"><Button onClick={() => interest.mutate({ requestId: opportunity.id, interested: true })} className="rounded-lg bg-[#0c6b58] text-white">Tenho interesse <Check size={15} /></Button><Button onClick={() => setActive(active === opportunity.id ? null : opportunity.id)} variant="outline" className="rounded-lg border-[#cbd8cc] bg-transparent text-[#0c6b58]">Enviar proposta</Button><Button onClick={() => interest.mutate({ requestId: opportunity.id, interested: false })} variant="ghost" className="rounded-lg text-[#8a968e]">Não tenho interesse</Button></div>{active === opportunity.id && <div className="mt-4 rounded-xl bg-white p-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Valor da proposta (R$)" value={proposalForm.amount} onChange={v => setProposalForm({ ...proposalForm, amount: v })} placeholder="450" /><Field label="Prazo" value={proposalForm.deadline} onChange={v => setProposalForm({ ...proposalForm, deadline: v })} placeholder="Até 3 dias úteis" /></div><Field label="Como você pode ajudar" value={proposalForm.description} onChange={v => setProposalForm({ ...proposalForm, description: v })} placeholder="Explique o diagnóstico e o que será feito" /><Button disabled={sendProposal.isPending} onClick={() => sendProposal.mutate({ requestId: opportunity.id, amount: Number(proposalForm.amount), deadline: proposalForm.deadline, description: proposalForm.description, notes: proposalForm.notes })} className="mt-3 rounded-lg bg-[#0c6b58] text-white">Enviar proposta</Button></div>}</div>)}</div>}</CardContent></Card></div></div>;
}

function AdminPanel() {
  const { data: metrics, isLoading } = trpc.admin.metrics.useQuery();
  const { data: recent } = trpc.admin.recent.useQuery();
  const cards = [{ key: "customers", label: "Clientes", icon: <CircleUserRound /> }, { key: "professionals", label: "Profissionais", icon: <Wrench /> }, { key: "requests", label: "Solicitações", icon: <FileText /> }, { key: "matches", label: "Matches", icon: <Search /> }, { key: "interests", label: "Interesses", icon: <Check /> }, { key: "proposals", label: "Propostas", icon: <Sparkles /> }, { key: "hires", label: "Contratações", icon: <BriefcaseBusiness /> }, { key: "reviews", label: "Avaliações", icon: <Star /> }];
  return <div className="container py-8 md:py-10"><div><p className="text-sm text-[#6d776f]">Visão operacional</p><h2 className="display mt-2 text-3xl font-semibold md:text-4xl">Pulso do marketplace</h2></div>{isLoading ? <Loader2 className="mt-10 animate-spin" /> : <><div className="mt-8 grid grid-cols-2 gap-3 md:grid-cols-4">{cards.map(card => <div key={card.key} className="rounded-2xl border border-[#dce4da] bg-[#fffdf8] p-4"><div className="flex items-center justify-between"><span className="text-[#0c6b58]">{card.icon}</span><span className="display text-2xl font-semibold">{(metrics as any)?.[card.key] ?? 0}</span></div><p className="mt-3 text-sm text-[#718079]">{card.label}</p></div>)}</div><div className="mt-8 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><Card className="border-[#dce4da] bg-[#fffdf8] shadow-none"><CardHeader><CardTitle className="text-lg">Funil de liquidez</CardTitle><p className="text-sm text-[#718079]">Da demanda até a reputação.</p></CardHeader><CardContent><div className="space-y-3">{[["Solicitação", metrics?.requests ?? 0, "bg-[#dff0e7]"], ["Match", metrics?.matches ?? 0, "bg-[#d0e2f7]"], ["Proposta", metrics?.proposals ?? 0, "bg-[#e8ddf5]"], ["Contratação", metrics?.hires ?? 0, "bg-[#f7dfb1]"], ["Conclusão", metrics?.completed ?? 0, "bg-[#dff4dc]"], ["Avaliação", metrics?.reviews ?? 0, "bg-[#f5d4c5"]].map(([label, value, color]: any, i) => <div key={label} className="flex items-center gap-3"><span className="w-24 text-xs font-semibold text-[#66746c]">{label}</span><div className="h-9 flex-1 overflow-hidden rounded-lg bg-[#eef1eb]"><div className={`flex h-full items-center rounded-lg px-3 text-sm font-bold ${color}`} style={{ width: `${Math.max(12, Math.min(100, Number(value) * 12 + 12))}%` }}>{value}</div></div>{i < 5 && <ChevronRight size={15} className="text-[#a3afa7]" />}</div>)}</div></CardContent></Card><Card className="border-[#dce4da] bg-[#0b332d] text-white shadow-none"><CardHeader><CardTitle className="text-lg">Solicitações recentes</CardTitle></CardHeader><CardContent>{recent?.length ? <div className="space-y-3">{recent.slice(0, 5).map((request: any) => <div key={request.id} className="flex items-center justify-between border-b border-white/10 pb-3 last:border-0"><div><p className="font-semibold">#{request.id} · {request.serviceType}</p><p className="mt-1 text-xs text-white/55">{request.city} · {formatDate(request.createdAt)}</p></div><Badge className="border-0 bg-white/10 text-[#e3f3a4]">{statusLabels[request.status]}</Badge></div>)}</div> : <p className="text-sm text-white/60">Aguardando a primeira solicitação da operação.</p>}</CardContent></Card></div></>}</div>;
}

function RequestForm({ onBack }: { onBack: () => void }) {
  const { data: citiesData } = trpc.catalog.cities.useQuery();
  const cities = citiesData?.length ? citiesData : fallbackCities;
  const problemOptions = [
    { value: "ar_nao_gela", label: "Meu ar não está gelando" },
    { value: "ar_nao_liga", label: "Meu ar não liga" },
    { value: "ar_pingando", label: "Meu ar está pingando" },
    { value: "ar_barulho", label: "Meu ar está fazendo barulho" },
    { value: "instalar_ar", label: "Quero instalar um ar" },
    { value: "limpar_ar", label: "Quero limpar meu ar" },
    { value: "geladeira_freezer", label: "Minha geladeira ou freezer parou" },
    { value: "outro", label: "Outro problema" },
    { value: "ajuda", label: "Não sei — preciso de ajuda" },
  ];
  const [form, setForm] = useState({ problem: "", details: "", environment: "Casa", city: cities[0], address: "", urgency: "normal" as "normal" | "urgente" | "emergencial", availability: "Posso combinar" });
  const [files, setFiles] = useState<File[]>([]);
  const [reviewing, setReviewing] = useState(false);
  const selected = problemOptions.find(option => option.value === form.problem);
  const upload = trpc.requests.uploadMedia.useMutation();
  const create = trpc.requests.create.useMutation({ onSuccess: async (result) => { try { for (const file of files) { const dataBase64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("Não foi possível ler o arquivo")); reader.readAsDataURL(file); }); await upload.mutateAsync({ requestId: result.id, fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp" | "video/mp4" | "video/quicktime", dataBase64 }); } toast.success(`Solicitação enviada. ${result.matched} profissional(is) encontrado(s).`); onBack(); } catch (error) { toast.error(error instanceof Error ? error.message : "A solicitação foi criada, mas não foi possível enviar a mídia."); onBack(); } }, onError: (e) => toast.error(e.message) });
  const set = (key: string, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  const submit = () => { if (selected) setReviewing(true); };
  const confirm = () => { if (!selected) return; create.mutate({ problem: selected.value as "ar_nao_gela" | "ar_nao_liga" | "ar_pingando" | "ar_barulho" | "instalar_ar" | "limpar_ar" | "geladeira_freezer" | "outro" | "ajuda", details: form.details, environment: form.environment as "Casa" | "Apartamento" | "Loja" | "Empresa", city: form.city, address: form.address, urgency: form.urgency, availability: form.availability }); };
  const addFiles = (picked: FileList | null) => { if (!picked) return; const allowed = Array.from(picked).filter(file => ["image/jpeg", "image/png", "image/webp", "video/mp4", "video/quicktime"].includes(file.type) && file.size <= 12 * 1024 * 1024); setFiles(prev => [...prev, ...allowed].slice(0, 3)); if (allowed.length < picked.length) toast.error("Use até 3 arquivos de imagem ou vídeo com no máximo 12 MB cada."); };
  return <div className="min-h-screen bg-[#f7f4ee]"><div className="border-b border-[#dce4da] bg-[#fbfaf5]"><div className="container flex h-20 items-center justify-between"><button onClick={onBack} className="text-[#6d776f] hover:text-[#0c6b58]">← Voltar</button><Logo /><span className="hidden text-sm text-[#7f8b84] sm:block">Nova solicitação</span></div></div><main className="container max-w-3xl py-10 md:py-14"><div className="mb-10"><p className="text-xs font-bold uppercase tracking-[.18em] text-[#0c6b58]">{reviewing ? "Confira antes de enviar" : "Conte o que aconteceu"}</p><h1 className="display mt-3 text-4xl font-semibold md:text-5xl">{reviewing ? "Está tudo certo?" : "Nós encontramos quem resolve."}</h1><p className="mt-4 text-lg leading-8 text-[#6d776f]">{reviewing ? "Revise os dados abaixo. O profissional cuidará da parte técnica." : "Você não precisa saber o nome técnico do problema. Conte com suas palavras e deixe a plataforma fazer o trabalho pesado."}</p></div>{reviewing ? <Card className="border-[#dce4da] bg-[#fffdf8] shadow-[0_18px_50px_rgba(23,33,27,.06)]"><CardContent className="space-y-6 p-6 md:p-9"><div className="rounded-2xl bg-[#e8efe9] p-5"><p className="text-xs font-bold uppercase tracking-[.16em] text-[#0c6b58]">Problema informado</p><h2 className="mt-2 text-2xl font-bold">{selected?.label}</h2><p className="mt-2 text-sm text-[#52645a]">{form.environment} · {form.city} · {form.availability}</p>{form.details && <p className="mt-3 text-sm leading-6 text-[#52645a]">“{form.details}”</p>}</div>{files.length > 0 && <div><p className="text-sm font-bold">Arquivos anexados</p><div className="mt-2 flex flex-wrap gap-2">{files.map(file => <span key={`${file.name}-${file.size}`} className="rounded-full bg-[#f2e5bd] px-3 py-1 text-xs font-semibold text-[#76530a]">{file.name}</span>)}</div></div>}<div className="flex flex-col gap-3 sm:flex-row"><Button variant="outline" onClick={() => setReviewing(false)} className="h-12 flex-1 rounded-xl border-[#cbd8cc] bg-transparent text-[#0c6b58]">Voltar e editar</Button><Button disabled={create.isPending || upload.isPending} onClick={confirm} className="h-12 flex-1 rounded-xl bg-[#0c6b58] font-bold text-white">{create.isPending || upload.isPending ? <Loader2 className="animate-spin" /> : <Check size={18} />} Confirmar e encontrar quem resolve</Button></div></CardContent></Card> : <Card className="border-[#dce4da] bg-[#fffdf8] shadow-[0_18px_50px_rgba(23,33,27,.06)]"><CardContent className="space-y-8 p-6 md:p-9"><div><h2 className="text-xl font-bold">O que aconteceu?</h2><p className="mt-1 text-sm text-[#718079]">Escolha a opção que mais se aproxima. Se não souber, tudo bem.</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{problemOptions.map(option => <button key={option.value} type="button" onClick={() => set("problem", option.value)} className={`rounded-2xl border p-4 text-left text-sm font-semibold transition ${form.problem === option.value ? "border-[#0c6b58] bg-[#dff0e7] text-[#0c6b58] shadow-sm" : "border-[#dce4da] bg-[#fbfaf5] text-[#34443b] hover:border-[#9bc9af]"}`}>{option.label}</button>)}</div></div><label className="block text-sm font-semibold">Quer contar mais alguma coisa? <span className="font-normal text-[#8b978f]">(opcional)</span><textarea value={form.details} onChange={e => set("details", e.target.value)} className="mt-2 min-h-[100px] w-full rounded-xl border border-[#dce4da] bg-[#fbfaf5] px-4 py-3 text-sm leading-6 outline-none transition focus:border-[#8ab9a3] focus:ring-2 focus:ring-[#cde5d5]" placeholder="Ex.: Começou a fazer um barulho estranho ontem." /></label><div><div className="flex items-end justify-between gap-4"><div><h2 className="text-xl font-bold">Foto ou vídeo</h2><p className="mt-1 text-sm text-[#718079]">Opcional, mas ajuda o profissional a entender o chamado.</p></div><label className="cursor-pointer rounded-xl border border-[#bed3c5] bg-[#e8efe9] px-4 py-3 text-sm font-bold text-[#0c6b58]">Adicionar<input type="file" className="hidden" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" multiple onChange={e => addFiles(e.target.files)} /></label></div>{files.length > 0 && <div className="mt-3 flex flex-wrap gap-2">{files.map(file => <span key={`${file.name}-${file.size}`} className="rounded-full bg-[#f2e5bd] px-3 py-1 text-xs font-semibold text-[#76530a]">{file.name}</span>)}</div>}</div><div><h2 className="text-xl font-bold">Onde está o problema?</h2><div className="mt-4 grid gap-3 sm:grid-cols-4">{["Casa", "Apartamento", "Loja", "Empresa"].map(option => <button key={option} type="button" onClick={() => set("environment", option)} className={`rounded-xl border px-3 py-3 text-sm font-semibold ${form.environment === option ? "border-[#0c6b58] bg-[#dff0e7] text-[#0c6b58]" : "border-[#dce4da] bg-[#fbfaf5] text-[#52645a]"}`}>{option}</button>)}</div></div><div className="grid gap-5 sm:grid-cols-2"><SelectField label="Onde você está?" value={form.city} onChange={v => set("city", v)} options={cities.map((x: string) => ({ value: x, label: x }))} /><Field label="Endereço ou bairro" value={form.address} onChange={v => set("address", v)} placeholder="Opcional por enquanto" /></div><div><h2 className="text-xl font-bold">Quando você precisa?</h2><div className="mt-4 grid gap-3 sm:grid-cols-4">{[{ value: "emergencial", availability: "Agora", label: "Agora" }, { value: "urgente", availability: "Hoje", label: "Hoje" }, { value: "urgente", availability: "Amanhã", label: "Amanhã" }, { value: "normal", availability: "Posso combinar", label: "Posso combinar" }].map(option => <button key={option.label} type="button" onClick={() => setForm(prev => ({ ...prev, urgency: option.value as "normal" | "urgente" | "emergencial", availability: option.availability }))} className={`rounded-xl border px-3 py-3 text-sm font-semibold ${form.availability === option.availability ? "border-[#0c6b58] bg-[#dff0e7] text-[#0c6b58]" : "border-[#dce4da] bg-[#fbfaf5] text-[#52645a]"}`}>{option.label}</button>)}</div></div><div className="flex items-start gap-3 rounded-2xl bg-[#e8efe9] p-4 text-sm text-[#476052]"><ShieldCheck className="mt-0.5 shrink-0 text-[#0c6b58]" size={18} /><p>Você descreve o problema. O profissional cuida da parte técnica. Seus arquivos ficam ligados somente à sua solicitação.</p></div><Button disabled={!selected} onClick={submit} className="h-14 w-full rounded-2xl bg-[#0c6b58] text-base font-bold text-white hover:bg-[#095443]"><Check size={18} /> Revisar solicitação</Button></CardContent></Card>}</main></div>;
}

function Field({ label, value, onChange, placeholder, type = "text" }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string }) { return <label className="block text-sm font-semibold">{label}<input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className="mt-2 h-12 w-full rounded-xl border border-[#dce4da] bg-[#fbfaf5] px-4 text-sm font-normal outline-none transition focus:border-[#8ab9a3] focus:ring-2 focus:ring-[#cde5d5]" /></label>; }
function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: { value: string; label: string }[] }) { return <label className="block text-sm font-semibold">{label}<select value={value} onChange={e => onChange(e.target.value)} className="mt-2 h-12 w-full rounded-xl border border-[#dce4da] bg-[#fbfaf5] px-4 text-sm font-normal outline-none transition focus:border-[#8ab9a3] focus:ring-2 focus:ring-[#cde5d5]">{options.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label>; }
function Stat({ label, value, icon }: any) { return <div className="rounded-2xl border border-[#dce4da] bg-[#fffdf8] p-4"><div className="flex items-center justify-between"><span className="text-[#0c6b58]">{icon}</span><span className="display text-2xl font-semibold">{value}</span></div><p className="mt-3 text-sm text-[#718079]">{label}</p></div>; }
function EmptyState({ icon, title, copy, action, onClick }: any) { return <div className="rounded-2xl border border-dashed border-[#cbd8cc] bg-[#fbfaf5] px-5 py-10 text-center"><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-[#e8efe9] text-[#0c6b58]">{icon}</div><h3 className="mt-5 font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#718079]">{copy}</p>{action && <Button onClick={onClick} className="mt-5 rounded-xl bg-[#0c6b58] text-white">{action}</Button>}</div>; }

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [view, setView] = useState<"landing" | "dashboard" | "request">("landing");
  const [persona, setPersona] = useState<Persona>("customer");
  const beginCustomer = () => { if (!isAuthenticated) { startLogin(); return; } setPersona("customer"); setView("request"); };
  const beginProfessional = () => { if (!isAuthenticated) { startLogin(); return; } setPersona("professional"); setView("dashboard"); };
  const openDashboard = () => { if (!isAuthenticated) { startLogin(); return; } setView("dashboard"); };
  const handleLogout = async () => { await logout(); setView("landing"); toast.success("Você saiu da sua conta"); };
  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f7f4ee]"><Loader2 className="animate-spin text-[#0c6b58]" /></div>;
  if (view === "request") return <RequestForm onBack={() => setView("dashboard")} />;
  if (view === "dashboard" && isAuthenticated) return <Dashboard persona={persona} setPersona={setPersona} onRequest={() => { setPersona("customer"); setView("request"); }} user={user} onLogout={handleLogout} />;
  return <Landing onStart={beginCustomer} onProfessional={beginProfessional} onDashboard={openDashboard} user={user} onLogout={handleLogout} />;
}
